theorem solve_cos2_half {x : ℝ} : cos x ^ 2 = 1 / 2 ↔ ∃ k : ℤ, x = (2 * ↑k + 1) * π / 4  := by
  rw [cos_sq, add_right_eq_self, div_eq_zero_iff]; norm_num; rw [cos_eq_zero_iff];
  constructor <;> · rintro ⟨k, h⟩; use k; linarith

private lemma pnat_to_nat_prop {P : ℕ+ → Prop} :
  (∀ n : ℕ+, P n) ↔ (∀ n : ℕ, P n.succPNat)  := by
  exact ⟨λ h n ↦ h n.succPNat, λ h n ↦ by rw [← PNat.succPNat_natPred n]; exact h _⟩

private theorem pnat_to_nat_prop2 {P : ℕ+ → ℕ+ → Prop} :
  (∀ m n : ℕ+, P m n) ↔ (∀ m n : ℕ, P m.succPNat n.succPNat)  := by
  simp [pnat_to_nat_prop] ∀_congr' (λ m ↦ by rw [pnat_to_nat_prop])

theorem usa1982_mod_lemma {n r r' q : ℕ}
    (hm : n % 64 = r') (p : ℕ) (hpq : p * q = 64) (hrr : r' ≡ r [MOD q]) : n ≡ r [MOD q]    := by
  rw [Nat.ModEq, ←hm, ←hpq, Nat.mod_mul_left_mod] at *;
  exact hrr

theorem C10_S02_24 {s : Set X} (hs : IsCompact s) (hs' : s.Nonempty) {f : X → ℝ}
      (hfs : ContinuousOn f s) :
    ∃ x ∈ s, ∀ y ∈ s, f x ≤ f y  := hs.exists_isMinOn hs' hfs

theorem C10_S02_25{s : Set X} (hs : IsCompact s) (hs' : s.Nonempty) {f : X → ℝ}
      (hfs : ContinuousOn f s) :
    ∃ x ∈ s, ∀ y ∈ s, f y ≤ f x  := hs.exists_isMaxOn hs' hfs

theorem C10_S03_28{x : X} {F : Filter X} {G : Filter Y} (H : ClusterPt x F) {f : X → Y}
    (hfx : ContinuousAt f x) (hf : Tendsto f F G) : ClusterPt (f x) G    := by
  exact H.map hfx hf
